   "s7_title": "打开书本轮读（一）：两个基督教的冲突 & 1900年的世纪婴儿",
   "reading_1": [
    "📖 朗读选段一：“中华归主”还是“主归中华”？（请翻开原书 P.28 第2段 – P.30 第1段）",
    "“一个是基要派的基督教，可以叫‘中华归主’基督教。一个是自由派的基督教，可以叫‘主归中华’基督教。这就是家庭教会和三自爱国会的最初源头。其实中华归主的英文，来自杨格非的一句名言，他说我们来到中国，不是为这样，也不是为那样，唯一的目的是‘为基督征服中国’。但到了20世纪，这个说法已经被宣教士们不耻了。19世纪‘为基督’，20世纪‘为中国’。19世纪的宣教士对中国文化毫不妥协，20世纪的宣教士对中国文化十分热爱……\n1910年的爱丁堡宣教大会，年轻的陈静怡在大会上宣称，教会一直都是 church in China（在中国的教会）。但现在我们需要 church of China（属中国的教会）。中国人要有中国人自己的教会。其实这是三自爱国运动最初的版本，就是‘一个民族主义的教会梦’。但这个梦不是把教会的梦做大了，而是把教会的梦做小了。从这时开始，本土的自由派领袖开始登上舞台，教会梦开始成为中国梦的一个支部。”"
   ],
   "reading_2": [
    "📖 朗读选段二：平信徒福音运动与“1900年的世纪婴儿”（请翻开原书 P.31 第2段 – P.32 第2段）",
    "“中国家庭教会，在本质上是一个平信徒福音运动。它是从平信徒兴起来的一个教会运动……直到1920年代初，华人牧师的数量，才开始恢复到1899年庚子教难之前的水平。花了整整20年。但是上帝做了一件非常奇妙的事，就是在1900年前后，为中国教会预备了一批‘世纪婴儿’。这批世纪婴儿，到20年代后陆续登上教会舞台，然后上帝使用他们，赐下了1927-1937的大复兴，形成了中国本土的基要派教会传统……\n这批教会的世纪婴儿都在庚子年前后相继出世。唐崇荣牧师曾说，‘这表明神是历史的主宰。你杀掉一批，我就生一批更伟大的出来’……到了1920年代，当他们一登上中国教会的舞台，教会的属灵领导权和属灵权威，以及19世纪宣教士向我们所传的那个基要派的福音，就整体上从宣教士群体，转移到本土传道人群体了。”"
   ],
   "s8_title": "打开书本轮读（二）：教会学校的反讽 & 华北神学院与宋尚节",
   "reading_3": [
    "📖 朗读选段三：为什么教会学校学生成了反教主力？（请翻开原书 P.34 第2段 – 第4段）",
    "“关于基督教教育，我们常反思一件事，就是在‘非基督教运动’和‘收回教育权运动’中的一个反教主力，就是教会学校的学生群体。带头上街示威游行，带头反对宣教士，带头要求‘请把我们收回为中国学校吧’的，竟然就是教会学校的学生们……\n这正是自由派神学，这‘另一个基督教’在中国形成所导致的局面。当宣教士们离开了灵魂得救的福音焦点，把教育从‘为基督’变成了‘为中国’，从‘为教会’变成了‘为社会’。教会学校所培养的绝大多数人，就都是随从世界潮流的人……那些受自由派神学影响的宣教士们，太想通过传扬基督教来改变中国现实。怜悯和文化事工的目标，开始步步压倒福音的焦点……此消彼长，短短20年后，中国教会就自食其恶果了。”"
   ],
   "reading_4": [
    "📖 朗读选段四：华北神学院的出走与“宋疯子”扔文凭（请翻开原书 P.40 第2–4段 & P.43 第2–3段）",
    "“因为齐鲁大学神学院逐渐受到自由派影响，院长就是赫士。他就带着几个教授，还有当时18个学生，集体出走。在山东滕县建立了‘华北神学院’……有诗为证：秀生作先锋，赫士成基石。耶稣是基督，教会进家庭。赫士在20年代写了一篇文章，批判自由派神学对教会的腐蚀，尤其是对教育的毒害。他说，今天中国的教会学校，‘将被证明是通往共产主义的道路’。这真是先知的话……\n宋尚节决定去纽约协和神学院读书。但这个神学院当时是自由派的大本营……于是他就呼召老师悔改，呼召同学悔改，说你们要重生。结果院长就把他送到精神病医院去了。他在里边关了半年多，把圣经读了很多遍，也经历到圣灵特别的带领。于是宋尚节启程回国，在船上就把博士文凭扔海里了。回来后，就成了一个奋兴布道家。”"
   ],
