   "prayer_guide": "• 前 7 分钟（两三人一组简短代祷）：① 为我们常常追求世俗认同、缺乏宋尚节与王明道那样为主癫狂的心志悔改；② 为我们教会的儿女教育代祷，求主保守下一代不被世俗潮流掳去，成为新时代的“世纪婴儿”；③ 为教会同工合一、堵住破口代祷。\n• 后 3 分钟（全体起立或同声开口诵读下方原书 P.50–51《结束祷告》）：",
   "closing_prayer_title": "《第二章 · 结束祷告》（原书 P.50–51）",
   "closing_prayer_text": "“主，我们感谢赞美你。主啊，让我们来思想你的恩典，你总是为自己存留敬虔的后代，就像你在以色列的历史当中所做的一样，在20世纪的中国历史上你也是如此的做。人们不知道1900年的发生，但是你知道；人们不知道1919年的五四运动，但是你知道；人们不知道整个社会的革命浪潮，人们不知道1949年之后的政权，但是你知道。所以每一次你都有在你的教会当中有预备，都有在兴起，存留那个古旧福音的种子。\n\n主啊，你将我们和西方自由化的潮流隔绝，你将我们放在共产党的制度压迫之下，最终你给我们的是一个全世界最大的几千万人的保守派的教会，一个相信圣经权威的教会。主啊，这是你从石头中为你自己所兴起的教会，而且我们在这个过程当中见证的并不是我们的勇敢，并不是我们的坚固，主啊，而是你的教会的软弱，是你的教会的背叛……但是主啊，你怜悯我们，是你的心意在我们当中不失败，主啊，我们感谢赞美你，就求你使我们在你的面前长存感恩和信靠你的心，听我们如此的祷告祈求，奉主耶稣基督宝贵的圣名。阿门！”",
   "s14_tag": "下周预习预告",
