   "s7_title": "打开书本轮读（一）：毕范宇的先知预言 & 王明道的跌倒与恩典",
   "reading_1": [
    "📖 朗读选段一：毕范宇的“乡村与家庭”预言 vs 周恩来三条限制（请翻开原书 P.54 第2–4段 & P.56 第1–2段）",
    "“在1949年前夕，第一个提出建立‘家庭教会’作为应急方案的，也是长老会的牧师，即当时上海国际礼拜堂的毕范宇……毕范宇牧师提出共产党进城后的两个应急策略。第一，教会必须将重心从城市转向乡村，建立农村教会；第二，教会必须预备采用‘家庭聚会’的方式，在未来的严酷局势下，像初代教会一样星罗棋布地分散存在。两个关键词，一是乡村，二是家庭。之后整整半个世纪，中国教会的历史轨迹，恰如毕范宇牧师所预言的一样……\n周恩来提出教会可以被允许在新中国存在的三个条件：一是对外与帝国主义划清界限；二是对内清查队伍，揪出‘反革命和坏分子’；三是不能再上街去传福音，发单张，信仰活动只能被限定在经批准的宗教场所……半个世纪以来，中国的教会都下意识地认为，‘生存’是一间教会的最高目标。而‘惧怕’也成为了中国家庭教会最基本的生命经验。”"
   ],
   "reading_2": [
    "📖 朗读选段二：王明道狱中唱《一切全完了》与唯独恩典（请翻开原书 P.62 第1段 – P.63 第2段）",
    "“罪人都是软弱的，王明道也如此，我们都很尊敬的被主大大使用的忠仆，他在刀剑面前，也一度软弱到这样一个愚蠢的地步。所以，他出来后就停止了所有服事，但也没有加入三自。他知道自己跌倒了，就闭门思过，向主悔改。有首诗歌叫《一切全献上》，他在监狱里想到这首歌，就改写了歌词，叫‘一切全完了’。你看他崩溃到这个地步。我们的信心，高也从未高到王明道的地步，但低也从未低到王明道的地步。所以我们是浅尝辄止的基督徒，而他是被福音大大充满和使用的一个‘伟大的罪人’。\n你在家里没有说，‘一切全完了’，但他在狱中会唱‘一切全完了’。这显明神确实是从粪堆中提拔人的神，也显出中国教会的道路，是唯独恩典的道路。不是因为教会有几个很了不起的人，道德灵命杰出的人，所以才复兴了……连你的软弱和跌倒，同样可能成为上帝使用你侍奉他的方式。”"
   ],
   "s8_title": "打开书本轮读（二）：王明道的同案犯 & “家庭教会的修道院就是监狱”",
   "reading_3": [
    "📖 朗读选段三：我们都是“王明道的同案犯”（请翻开原书 P.65 第2段 & P.67 第2段）",
    "“简单来说，在1955年之后，直到今天，中国家庭教会其实都是王明道的同案犯。因为王明道的‘反革命集团’案迄今也没有平反。换言之，王明道对这个共和国来说，仍然是一个罪犯。如果今天我们持定跟这个罪犯一样的信仰立场，我们就仍然同属于‘王明道反革命集团’……亲爱的弟兄姊妹，若为主的缘故披上这些罪名是荣耀无比的事。在这个政权没有平反教案、或没有改变它打击基督教的立场之前，这些罪名就是主基督在中国的荆棘冠冕……逼迫是上帝的礼物，是教会的健身房。逼迫显明一件事，就是我们的信仰是来真的。\n贾玉铭大概太想保住自己的事工和神学院……所以，如果上帝拿掉你的一份工作，你要赞美主。因为下次逼迫来的时候，你要放弃的东西就少了一件。如果上帝提前剥夺了你的出版，你的地位，那么当逼迫来的时候，你在这些方面就不会被世界威胁。”"
   ],
   "reading_4": [
    "📖 朗读选段四：监狱成了修道院——神为家庭教会存留血脉（请翻开原书 P.68 末段 – P.69 末段）",
    "“令人敬畏的一点是，加入三自的教会领袖，大部分都活得不长，多数都死于文革。但家庭教会的领袖，那些在55-56年被捕、在57年反右中被捕、或在文革前就被关押、下放的人，到了80年代初全都放了出来，大部分都还活着，而且基本上都活到80-90岁……这里隐藏着上帝极大的恩典。为什么呢？因为最残酷的文革来临时，这些1949年前的基要派教会领袖，都被神保护起来了。保护在哪里呢，他们都被保护在监狱里！\n所以家庭教会的修道院，就是监狱。家庭教会的传道人，要等着坐牢才有安息年。这是神特别给中国教会存留的恩典……这不单是他们个人和家庭蒙了祝福，更重要的是，神存留他们的性命是为着我们。这是给家庭教会留一个传承，一个血脉。没有这一批坐过牢、经过火炼的基要派传道人的老当益壮，就没有1980年后中国家庭教会的复兴。”"
   ],
