   "closing_prayer_text": "【同诵经文 · 弥迦书 7:7–9】\n“至于我，我要仰望耶和华，要等候那救我的神。我的神必应允我。我的仇敌啊，不要向我夸耀。我虽跌倒，却要起来。我虽坐在黑暗里，耶和华却作我的光。我要忍受耶和华的恼怒，因我得罪了他；直等他为我辨屈，为我伸冤。他必领我到光明中，我必得见他的公义。”\n\n【同声感恩祷告（化用原书 P.62, 69）】\n“主啊，我们感谢赞美你！你是从粪堆中提拔人的神，中国家庭教会的道路，从来不是靠人的刚强与勇敢，而是唯独恩典的道路！感谢你在最严酷的年代，将你的仆人们藏在监狱的修道院中，存留他们的性命，为家庭教会留下一条属灵的传承与血脉。主啊，求你赦免我们的软弱与惧怕，帮助我们在今天的世代坚定站立，以背负主基督的荆棘冠冕为我们的荣耀！因为唯有主的名是配得称颂的。奉主耶稣基督宝贵的圣名祷告，阿们！”",
