   "s7_title": "打开书本轮读（一）：革命美学的冲击 & 叶乃光“新人不齐，新日不至”",
   "reading_1": [
    "📖 朗读选段一：为什么“革命美学”俘虏了年轻一代？（请翻开原书 P.74 第2–4段）",
    "“三自运动并非仅仅依靠了革命的暴力，而且首先依靠了革命的美学，就是意识形态的伪崇高和偶像崇拜。共产党人论到祖国的未来时说，‘我们中间的党团员，我们没有给你们留下一个袖珍的新耶路撒冷，给你们留下的是一个960万平方公里一穷二白的中国，你们在上面可画最美最好的图画’。这种革命美学，俘虏了教会中的年轻一代。因此燕大在并入北大之前，学生团契就基本上一扫而光了。大多数人都失去信仰，其中包括王明道的儿子。\n一方面，我们感谢主，为家庭教会存留了基要派信仰，在大逼迫中持守了福音。但另一方面，有少数老仆人都很诚实的讲，是神的手拆毁了中国教会……家庭教会史让我们看见，无论是一种跟随时代潮流的信仰，还是一种与时代潮流脱节、躲进小楼成一统的信仰，其实都无法回应这翻天覆地的变局。”"
   ],
   "reading_2": [
    "📖 朗读选段二：13年地上无教会与叶乃光的八字预言（请翻开原书 P.80 第2–3段 & P.81 末段 – P.82 第2段）",
    "“1966年-1979年，整整13年中国没有一间教会。在上海，张春桥宣布说：‘中国已经没有基督教了。’江青也宣布说：‘我们只用了几个月，就把基督教扫进了历史的博物馆。’毛泽东最后一次在中南海见到吴耀宗，对他挑衅说，‘你那个上帝最近不太灵啰’……然而神对教会总有特别的熬炼与保守，13年来地上虽无一间教会，无一位牧师，无一位长老。但家庭教会却进入它的第三个高峰期。\n1968年，杨安溪去见叶乃光，问他同样的问题：‘中国教会还有没有希望？’叶乃光说了八个字，‘新人不齐，新日不至’。他解释说：前几十年上帝在中国教会是做‘养育’的工作，这几十年神要做‘拆毁’的工作。等这几十年过完了，新人齐备，新日才会到，中国教会就要进入‘倒输’的工作。倒输的意思就是向国外传福音。”"
   ],
   "s8_title": "打开书本轮读（二）：半夜灶台旁的祷告 & 牛棚鞭打中的圣灵充满",
   "reading_3": [
    "📖 朗读选段三：批斗会变布道会与“夜晚的精神世界”（请翻开原书 P.83 第2段 & P.86 第2段）",
    "“如方城的前辈传道人高允玖长老，文革前就坐牢，坚决不加入三自。文革中多次被批斗，游街。有意思的是，在河南，批斗会成了最主要的布道会。干部和民兵让他坦白交待，他就借机向群众传福音，向乡亲们见证信主可以病得医治，现在被批斗，但灵魂可以上天堂。文革后期方城一批年轻传道人，都听过批斗会，都受过高长老的影响……\n以前学者朱学勤跟我讲一个故事，他没有信主，文革中被下放，住在当地一个根红苗正的老太太家里。最纯正的贫下中农，还作为典型上过报纸。半夜他起来解手，发现老太太跪在灶台旁，叽咕叽咕，不知说些什么。他不好打扰，忽然意识到，她是在祷告……原来文革中全国江山一片红，不革命的都被抓起来了，但竟然还有一个地下形态，还有一个夜晚的精神世界，还有一个秘密社会仍然存在，并没有被共产党消灭，那就是教会。”"
   ],
   "reading_4": [
    "📖 朗读选段四：杨安溪在牛棚鞭打中经历圣灵充满（请翻开原书 P.88 第1段 – 末段）",
    "“杨安溪的见证，他从57年信仰崩溃后，就在神面前求圣灵充满，使他恢复信心，祷告了17年，神都没有给他。最后在文革中，他被关牛棚，被一个看守绑起来，用鞭子鞭打了三个半小时，直到快死了，这时他忽然经历到圣灵充满……告发他的人崩溃了，跑过来给他说对不起，那人甚至倒在地上哭，以为他要被打死了。就在这时，杨安溪突然经历到圣灵充满，里面充满了一种力量，含隐不住，十分喜乐。他就跟神祷告：‘主啊，不要是这会儿吧，这是在牛棚，我现在被鞭打，又不能赞美你，又不能唱诗。我祈求了十几年，怎么这会儿给我呢？’于是他就饶恕了告他的人和鞭打他的人……\n圣灵就激动他，鼓起勇气找领导说：‘我的确做不到四个无限，我不可能无限信仰、无限热爱毛主席，你们不要把精力浪费在我这个死不悔改的基督徒身上了，我绝对不可能悔改的，你们要杀就杀，不要浪费时间了，我就这个样子。’亲爱的弟兄姊妹，这就是圣灵充满的结果，去找杀你的人摊牌，说死就死吧，我就是信耶稣。王明道经常送八个字，叫‘但遵神旨，莫问前程’。林献羔总结家庭教会的神圣原则，叫‘哪里有逼迫，哪里就有复兴’。因为圣灵充满的结果，就是十字架的道路。”"
   ],
