   "s7_title": "打开书本轮读（一）：死过又活过来的灯塔 & 观音像与巴比伦金像",
   "reading_1": [
    "📖 朗读选段一：城市中的孤岛灯塔与跨代积累（请翻开原书 P.92 第2–3段 & P.93 第2段）",
    "“1978到1982年，大城市中陆陆续续放出来一批传道人……这批老仆人，成了大复兴的中流砥柱。为什么说他们是标杆人物？因为那个时代的特征，是坐过牢的传道人比整间教会的影响力更大。坐了几十年牢的人，你再抓他也没什么意思。坐过牢的人出来，再建立一间教会，当地政府就得过且过，装做没看见了。因为生命的见证是很难征服的力量……任何时代都是这样，教会要走十字架的道路，走到一个地步，才能让世界睁只眼、闭只眼。你要付代价到底、死了又活过来，人家就装着没看见你。袁相忱在北京，林献羔在广州，还有杨心斐在厦门，李天恩在上海，都是如此。这些从1949年延续到1980年代的基要派教会，中间死过，后来又活了。一旦复活过来，就从来没有再被消灭过。\n因为教会不但是一个时代的圣徒团契，而且是历代教会的一个积累……欧洲一些大教堂，是用了超过一百年、甚至两百年才修好的。”"
   ],
   "reading_2": [
    "📖 朗读选段二：从基要派到福音派——砸观音像与辨别时代偶像（请翻开原书 P.94 末段 & P.96 第2–3段）",
    "“第一，每个时代都需要重新认识福音，不断把握和定睛于福音的焦点。第二，每个时代都需要认识福音使命在那个时代的处境和迫切性。有些东西永远不能变，因为那是福音的本质，但是面对每一个时代，你的信仰生活的外观和教会文化的形态，必须接受破碎，才不会变成福音的拦阻……\n虽然罪的本质自古以来都一样，但在不同的文化中会获得不同的表达，形成不同的结构。福音必须对现代意识形态说话，就如当初福音对着罗马文化和希腊哲学说话一样。现代的理性主义和自由主义怎么激起了人的罪并摧毁了福音的文化，现代的国家主义意识形态怎样重新竖立了巴比伦的金像。基要派几乎放弃了教会在基督里的先知和君王职分，从公共生活中退出，仅仅保留了私人祭司的角色。举例，中国的教会传统特别注重信主后不能拜偶像，家里的观音像一定要砸掉。这是对的。然而，我们对更广阔的社会文化里的偶像缺乏敏感，缺乏对话、辨别和弃绝的能力。”"
   ],
   "s8_title": "打开书本轮读（二）：珍珠计划与良友电台 & 拉紧窗帘的祷告",
   "reading_3": [
    "📖 朗读选段三：珍珠计划、半导体收音机与赵天恩牧师（请翻开原书 P.103 第1–3段）",
    "“另外一支复兴的力量，来自海外华人教会的大陆宣教。1981年6月18日，荷兰的福音机构‘敞开的门’，组织了一次雄心勃勃的‘珍珠计划’。由海上偷运100万本圣经进入潮汕地区。但在汕头海边，船只被军队拦截了。他们把一袋袋油布包的圣经扔进海里。其中一些被胆大的信徒和渔民打捞起来……\n文革中，为了使‘最高指示不过夜’，及时传达到千家万户，生产半导体收音机就成了一项政治任务，全国拼命生产收音机，结果却帮助了福音传播。良友电台在1964年收到第一封来自大陆的听众来信。1966年文革爆发，当年仍收到超过100封大陆来信……到1998年为止，30多年间，香港良友电台共收到大陆听众来信超过100,000封。海外华人教会的宣教士，最早进来的可能是1978年从香港进入广州的赵天恩牧师……改革开放之后，没有其他任何一位宣教士，对家庭教会的委身、理解、关爱和影响力，能够超过赵天恩牧师。”"
   ],
   "reading_4": [
    "📖 朗读选段四：三楼顶站岗的弟兄与拉着窗帘唱诗的童年（请翻开原书 P.106 末段 – P.107 末段）",
    "“我去到长江边上的一个聚会点，半夜起来解手，上三层楼顶，像以色列人的房子，是平顶。上去见一个弟兄在那里守夜，等候天明。我说：‘弟兄，你这么早来祷告？’他说，‘不是，是站岗’。他从楼顶就看到江对面，如果有警察来了，就赶紧报告。直到2005年，很多受逼迫的农村教会都还有这个习惯……\n我记得很多年前有个姐妹，她是从小信主，那时十七八岁了，有次她的祷告非常触动我。她说：‘主啊，为什么我们从小就必须把房间关得严严的，把窗帘完全拉起来才能向你祷告呢？为什么我们从小唱歌都必须小声的，把门关死了才能向你敬拜呢？’我当时听了心里特别难过。弟兄姐妹们，你们有一半人都不曾经历过‘地下教会’的时代，求主让我们看见，我们要在这时代为主来打美好的仗。不要看这一切是我们的福利，而要看我们今日得着王后的位分，是要为福音更加癫狂和付出。不要看我们今日的外在环境为不可放弃的，也绝不在逼迫的压力下，轻易放弃家庭教会用许多眼泪和祷告才换来的公开敬拜上帝的自由。”"
   ],
