    "“陈奎德先生说他们被送到巴黎，到了巴黎之后，他们那一行很多的人一下飞机，放下行李，立刻就去了巴黎圣母院。他们以前从来没去过教堂的，他们在里面看到有耶稣像的十字架，他们就跪下，他们不知道为什么要跪下来，但是他们就是跪下来，然后泪流满面……这个就代表了整个流亡一代民主败北后的虚空和迷茫，从而产生对信仰的渴慕和追求。\n八十年代到九十年代初是乡村教会的复兴……但是在接下来的几十年中，一直到今天，可能有一两千万的乡村基督徒进入城市，然后消失在城市之中……那乡村到了九十年代末两千年初的时候，已经变成什么样了呢？有一个词叫做‘三八、六一、九九部队’，三八妇女、六一儿童、九九老年人，所以男人就不见了，年轻人就不见了，一代的留守儿童，我们当中很多的都是留守儿童长大的。”"
