   "prayer_guide": "• 前 7 分钟（两三人一组简短代祷）：① 为我们里面的知识傲慢、看重外貌阶层、缺乏擘饼认罪的眼泪向主悔改；② 为城市里漂泊的信徒、老家的留守长辈与儿童代祷；③ 求主保守我们持定“唯独因信称义”，绝不向世俗妥协。\n• 后 3 分钟（全体起立或同声开口诵读下方原书 P.123《结束祷告》）：",
   "closing_prayer_title": "《第六章 · 结束祷告》（原书 P.123）",
   "closing_prayer_text": "“我们感谢主在中国教会中赐下的恩典，所带领的云彩般的见证人，我们求主继续托起带领中国教会，我们在主的面前立志说，主啊，我们愿意把自己献给你，求你自己来引领我们，让我们那悲喜的眼泪无数次的流过，但是我们知道羔羊你已经得胜，我们同声一起在主的面前开口来祷告，献上自己为祭。\n\n主啊，我们感谢你！主啊，孩子在你面前实在是看到那叙述你在我们当中的恩典的时候，就如同那以色列人来叙述你怎样带领他们经过红海，走过干地。主啊，你这样带领他们在旷野当中，你在中国教会的几十年中，主啊，你就是那位使乌鸦叼饼来养活你自己的仆人的主。主啊，我们实在是感谢赞美你，我们进入到一个新的时期，主啊，教会不断地跟社会接触，我们也看到主你在新时代对教会的引领。主，孩子感谢赞美你，就求主你自己在我们当中再一次的来引领我们，主啊，感谢赞美你！主啊，孩子在你面前说，求你来悦纳，求你自己来接近我们的心，以至于我们在这个新兴的城市教会中，主你实在是来带领我们！感谢赞美主！祷告奉主耶稣基督的名！阿们。”",
