     "title": "议题一：走出“悄悄做门徒”的隐藏——成为公开的光明之子",
     "banner": "💡 历史镜鉴：华南教案显明，长期封闭的地下秘密状态必然滋生权力腐败与真理偏差，因此教会必须公开化，成为“山上之城”（P.127-128）；而2003年看《十字架》纪录片时，身边的朋友竟悄悄做了多年基督徒而无人知晓（P.131）。",
     "q1_title": "💬 问题 1A：“你们也从来没有问过啊”——你是隐藏的门徒吗？",
