   "closing_prayer_text": "“主，我们感谢你！你是永恒的主，你给我们永恒的盼望，若不在你里面，一切都是短暂的，甚至连我们的信心，我们的跟随，我们的侍奉，其实都是短暂的。因为这一切若不是出于你而是出于自己的话，谁能够持守呢？谁能够保守呢？谁能够坚持到底呢？谁能够靠自己相信自己至终得救呢？\n\n主啊，求你怜悯我们，求你帮助我们，求你使今天的中国教会看到在这一路上主你的恩典，主啊，你的脂油滴满了我们脚下的道路。求你的爱在中国，求你的爱浇灌我们，使我们继续地向前，有一天我们要回到全地的教会的大家庭当中，我们要与万国的你的儿女一同敬拜你，也一同参与直到地极的福音的使命，和在你面前的直到永远的敬拜，感谢赞美神，听我们的祷告祈求，奉主耶稣宝贵的圣名，阿们！”",
