   "s7_title": "打开书本轮读（一）：主日学得着下一代 & 基督徒企业家的底线",
   "reading_1": [
    "📖 朗读选段一：为什么必须从“主日学两小时”走向“基督教教育”？（请翻开原书 P.141 第2段 & P.142 第2–3段）",
    "“在2017年9月到2018年的新一轮逼迫浪潮中，有一个很重要的方面就是禁止18岁以下的未成年人进入教会参加崇拜，不允许父母带他们的孩子去教会……在八十年代，温州教会顶住压力，建立起了儿童主日学。但是在河南教会、安徽教会和其他更多的地区的传统家庭教会中并没有成熟有力地建立起儿童主日学事工……\n河南教会、安徽教会基本上是失去了下一代。因为一个成熟的主日学系统没有建立起来，就没有办法在这个时代的浪潮来袭时再得着自己的后代了。到了2006年的时候，很多教会开始慢慢地看到主日学不够用。一个星期在主日学学习两个小时，但是公立学校要学五天，这个是不行的，后代还是在不断地失去。所以在2006年，出现了第一间家庭教会的教会学校……要把主日学变成日日学。”"
   ],
   "reading_2": [
    "📖 朗读选段二：基督徒企业家的底线与“最好也是最坏的时代”（请翻开原书 P.145 末段 – P.146 第3段）",
    "“我认识一个基督徒企业家，他跟我讲，在中国他持守一个原则，挣钱不超过五千万，做官不能超过处级。为什么呢？他说他公司差不多到五千万这个级别了，如果他再想挣钱，想做更大的项目，就必须要跟某个官员靠近了，就必须要跟这个体制同流合污了……\n这十年来，尤其是最近的五年来，中国社会发生一个很大的变化，就是逃离中国的运动……越来越多的人对这里悲观失望、对国家悲观失望、对社会的前途悲观失望，当然顺带对自己的前途也悲观失望。这个反而一方面给福音预备了人心，所以这八年来人心从来没有像今天这样被上帝预备，自改革开放以来这是最好的时代，这是最坏的时代！”"
   ],
   "s8_title": "打开书本轮读（二）：别想着去国宾馆 & 趁还有机会给弟兄姐妹洗脚",
   "reading_3": [
    "📖 朗读选段三：拒绝钓鱼台统战迷魂汤——“别想着去国宾馆！”（请翻开原书 P.149 末段 – P.150 第2段）",
    "“过了一年之后，大家基本上就认清局面了，这帮牧师就知道家庭教会的牧师最好不要去搞政治，你明白吗？有人说我们搞政治，我们连钓鱼台都不去。这跟我们没关系，我们是主的教会，跟政府没关系。跟政府搞得太拢，最后都是被人家骗的。\n你一定要知道我们这帮人不过就是信耶稣的人，我们的政治智慧在别人面前等于零，不要高看自己。你别跟他们玩，你信耶稣就好了。你该传道就传道，该植堂就植堂，该坐牢就坐牢。你别想着去国宾馆！”"
   ],
   "reading_4": [
    "📖 朗读选段四：万一下一周大逼迫来了，你就没机会给弟兄姐妹洗脚了（请翻开原书 P.151 末段 – P.153 第1段）",
    "“只要在，我就挑战你们，现在不全职的侍奉什么时候全职？现在不献身什么时候献身？所以我在上帝的面前祷告：‘要么我求主来一场大的逼迫，要么我求主在你们当中和在今天的中国教会中，求圣灵带来一场献身的运动，全职侍奉的运动’……\n首先我挑战每一位会友，我们不是说人人都有侍奉吗，你在这间教会如果还没有服事，我盼望你赶紧报名参加主日侍奉，好吗？因为没有几周了，万一下一周大逼迫就来了，你就没有机会给弟兄姐妹洗脚了。我们的爱宴需要同工，我们的主日接待团队需要更多的同工……这样你既是对弟兄姐妹的服事，对慕道友的服事，甚至也是你对那些已经在主日接待团队中的弟兄姐妹的服事，就是你来替他一次，你不要让他轮得太勤。这就是你的爱心，这就是你的服事。我们现在还有那么多的布道所，好几个布道所里面没有司琴，我们奉献几个司琴出去好不好？”"
   ],
