   "prayer_guide": "• 前 7 分钟（两三人一组简短代祷）：① 为教会的儿童主日学与基督教教育代祷，求主保守我们的下一代不流失；② 为我们在教会服事上的推诿懒惰悔改，求主在我们中间兴起更多全职传道人、神学生与忠心同工；③ 为受苦坐监的当代牧者代祷。\n• 后 3 分钟（全体起立或同声开口诵读下方原书 P.153《结束祷告》）：",
   "closing_prayer_title": "《第八章 · 结束祷告》（原书 P.153）",
   "closing_prayer_text": "“主，我们感谢赞美你。主啊，在2016年的时候，我们也看到一个标志性的事件就是90后年轻一代中的李欣恒和孟丽思两位肢体在巴基斯坦殉道。主，你带给我们一个过去的福音运动进入到尾声，整个社会都在剧烈的转型中，你也赐给了我们一个未来复兴的异象，甚至在那90后的年轻人中，你赐给中国教会，我们自己的司提反，我们这一代年轻的信徒中的殉道者。主，我们感谢赞美你，我们求你来带领这间教会，求你带领今天的各城各乡的中国教会，能够让我们快跑来跟随你，像我们所唱的这诗歌说：愿你赐我们这信心越来越刚强，主膀臂保护我们。\n\n很多人说为什么你们没事呢？我们回答说因为我们上面有主，因为我们有最大的保护伞，是遮盖着天地的保护伞。没有主的许可，没有一根头发可以掉在地上，没有一只麻雀可以掉在地上。主，我们这过去的十年中也看到许多你的仆人坐监入狱，甚至在拆十字架运动中也看到了顾约瑟牧师因为宣告脱离三自而被囚，也看到仰华牧师、金灯台教会、曹三强牧师还在监狱中。主啊，求你纪念这些仆人，求你使我们效法，我们不但是有历史上的圣徒可以效法，就在我们同一个时代，我们也有许多神忠心的仆人可以效法，这实在是你给我们极大的恩典。感谢赞美主，听我们如此的祷告祈求，奉主耶稣基督宝贵的圣名，阿们！”",
